function acceptedResponseOwnershipIssues(project,stage){
  const issues=[];
  for(const change of acceptedChanges(project,stage)){
    const proposal=safe(project.projectData.responseProposals).find(item=>item.proposalId===change.proposalId);
    for(const [collection,rows] of Object.entries(proposal?.envelope?.records||{})){
      const currentIds=new Set(recordsForCurrentScope(project,collection).filter(record=>record.sourceProposalId===change.proposalId).map(record=>recordId(record,collection)));
      for(const row of safe(rows)){
        const id=String(row.targetId||proposal.tempToCanonical?.[row.tempKey]?.id||'');
        if(!currentIds.has(id))continue;
        for(const name of Object.keys(row.fields||{})){
          const producer=schema.RECORD_SCHEMAS[collection]?.fieldDefinitions?.[name]?.producer;
          if(producer===schema.PRODUCER.AGENT)continue;
          const owner=producer?String(producer).toLowerCase().replaceAll('_','-'):'unregistered';
          issues.push(`The accepted response assigned ${owner}-owned field ${collection}.${name}. Correct and replace that response; its original evidence remains preserved.`);
        }
      }
    }
  }
  return [...new Set(issues)];
}

